head.script:
//
(function() {
  var saved = localStorage.getItem('md3_theme');
  var theme = saved ? saved : 'dark';
  document.documentElement.setAttribute('data-theme', theme);
})();
//

head.b:skin:
/*
<!-- Original Blogger Theme Designer Variables (Preserved for Compatibility) -->
<Variable name="keycolor" description="Main Color" type="color" default="#adc6ff" value="#adc6ff"/>
<Variable name="startSide" description="Start side" type="automatic" default="left" hideEditor="true"/>
<Variable name="endSide" description="End side" type="automatic" default="right" hideEditor="true"/>

<Group description="Theme Colors">
  <Variable name="body.background.color" description="Surface Background" type="color" default="#111318" value="#111318"/>
  <Variable name="posts.background.color" description="Card Surface" type="color" default="#202227" value="#202227"/>
  <Variable name="body.text.color" description="Body Text Color" type="color" default="#e2e2e9" value="#e2e2e9"/>
  <Variable name="body.link.color" description="Brand Primary Color" type="color" default="#adc6ff" value="#adc6ff"/>
  <Variable name="body.link.hover.color" description="Link Hover Color" type="color" default="#d8e2ff" value="#d8e2ff"/>
  <Variable name="body.link.visited.color" description="Link Visited Color" type="color" default="#adc6ff" value="#adc6ff"/>
  <Variable name="posts.title.color" description="Title Color" type="color" default="#e2e2e9" value="#e2e2e9"/>
  <Variable name="posts.text.color" description="Post Text Color" type="color" default="#c4c6d0" value="#c4c6d0"/>
  <Variable name="posts.byline.color" description="Byline Color" type="color" default="#8e9099" value="#8e9099"/>
</Group>
*/

/* ==========================================================================
   MATERIAL DESIGN 3 TOKENS (DEFAULT: DARK THEME)
   ========================================================================== */

:root,
html[data-theme='dark'] {
  --md-sys-color-primary: #adc6ff;
  --md-sys-color-on-primary: #002e69;
  --md-sys-color-primary-container: #004494;
  --md-sys-color-on-primary-container: #d8e2ff;

  --md-sys-color-secondary: #bfc6dc;
  --md-sys-color-on-secondary: #283041;
  --md-sys-color-secondary-container: #3f4759;
  --md-sys-color-on-secondary-container: #dbe2f9;

  --md-sys-color-surface: #111318;
  --md-sys-color-on-surface: #e2e2e9;
  --md-sys-color-surface-variant: #44474f;
  --md-sys-color-on-surface-variant: #c4c6d0;

  --md-sys-color-surface-container-lowest: #0c0e13;
  --md-sys-color-surface-container-low: #1a1c21;
  --md-sys-color-surface-container: #202227;
  --md-sys-color-surface-container-high: #282a2f;
  --md-sys-color-surface-container-highest: #33353a;

  --md-sys-elevation-1: 0 2px 8px rgba(0, 0, 0, 0.24);
  --md-sys-elevation-2: 0 4px 16px rgba(0, 0, 0, 0.32);
  --md-sys-elevation-3: 0 8px 24px rgba(0, 0, 0, 0.45);

  --md-sys-radius: 10px;

  --md-sys-font-brand: 'Roboto Flex', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --md-sys-font-plain: 'Roboto', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --md-sys-font-mono: 'Roboto Mono', ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;

  --md-layout-max-width: 760px;
  color-scheme: dark;
}

html[data-theme='light'] {
  --md-sys-color-primary: #005ac1;
  --md-sys-color-on-primary: #ffffff;
  --md-sys-color-primary-container: #d8e2ff;
  --md-sys-color-on-primary-container: #001a41;

  --md-sys-color-secondary: #575e71;
  --md-sys-color-on-secondary: #ffffff;
  --md-sys-color-secondary-container: #dbe2f9;
  --md-sys-color-on-secondary-container: #141b2c;

  --md-sys-color-surface: #fdfcff;
  --md-sys-color-on-surface: #1a1c1e;
  --md-sys-color-surface-variant: #e1e2ec;
  --md-sys-color-on-surface-variant: #44474f;

  --md-sys-color-surface-container-lowest: #ffffff;
  --md-sys-color-surface-container-low: #f4f0f6;
  --md-sys-color-surface-container: #eeeaef;
  --md-sys-color-surface-container-high: #e8e4ea;
  --md-sys-color-surface-container-highest: #e2dee4;

  --md-sys-elevation-1: 0 2px 8px rgba(0, 0, 0, 0.04);
  --md-sys-elevation-2: 0 4px 16px rgba(0, 0, 0, 0.08);
  --md-sys-elevation-3: 0 8px 24px rgba(0, 0, 0, 0.12);

  color-scheme: light;
}

/* ==========================================================================
   RESET & ZERO-LINE ARCHITECTURE
   ========================================================================== */

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  border: 0 !important;
  -webkit-tap-highlight-color: transparent;
}

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  overflow-x: hidden;
  background-color: var(--md-sys-color-surface);
  color: var(--md-sys-color-on-surface);
  font-family: var(--md-sys-font-plain);
  font-size: 16px;
  line-height: 1.6;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

.page_body, .centered, .main, #main, article, .post, .entry-content {
  overflow-wrap: break-word !important;
  word-break: normal !important;
  max-width: 100% !important;
}

.material-symbols-outlined {
  font-family: 'Material Symbols Outlined';
  font-size: 22px;
  line-height: 1;
  display: inline-block;
  vertical-align: middle;
  font-style: normal;
  user-select: none;
}

a {
  color: var(--md-sys-color-primary);
  text-decoration: none;
}

/* ==========================================================================
   SUPPRESSION OF UNWANTED MODULES
   ========================================================================== */

.FeaturedPost,
#page_body .FeaturedPost,
.widget.FeaturedPost,
.home-link,
.blog-pager-home-link,
#blog-pager-home-link,
a.home-link,
.blog-pager .home-link,
.post > .jump-link,
.post-share-buttons,
.post-share-buttons-top,
.post-share-buttons-bottom,
.share-buttons,
.sharing,
.sharing-button,
.sharing-platform-button,
.widget.Sharing,
.byline.post-share-buttons,
.sidebar-container,
#sidebar_top,
#sidebar_bottom,
aside,
.vertical-ad-container,
.hamburger-menu,
.PageList,
.BlogArchive,
.Label,
.LinkList,
.ReportAbuse,
.Image,
.HTML,
.bg-photo,
.bg-photo-overlay,
.bg-photo-container,
.centered-top-placeholder,
.navigation,
.search,
#search_top,
.BlogSearch,
.skip-navigation,
.PopularPosts,
.dim-overlay,
.feed-links,
.blog-feeds,
.post-feeds,
.subscribe-section-container,
.subscribe-popup,
#sharing-dim-overlay {
  display: none !important;
  visibility: hidden !important;
  width: 0 !important;
  height: 0 !important;
  overflow: hidden !important;
  margin: 0 !important;
  padding: 0 !important;
  pointer-events: none !important;
}

svg {
  max-width: 24px;
  max-height: 24px;
}

/* ==========================================================================
   SINGLE COLUMN & COMPACT SPACING
   ========================================================================== */

.page_body {
  position: static !important;
  margin: 0 auto !important;
  padding: 0 !important;
  max-width: 100% !important;
}

.page_body .centered {
  display: block !important;
  max-width: var(--md-layout-max-width) !important;
  width: 100% !important;
  margin: 0 auto !important;
  padding: 20px 16px 64px 16px !important;
}

@media (max-width: 640px) {
  .page_body .centered {
    padding: 8px 10px 40px 10px !important;
  }
}

.centered-bottom, .main, #main {
  width: 100% !important;
  max-width: 100% !important;
  padding: 0 !important;
  margin: 0 !important;
}

/* ==========================================================================
   TOP APP BAR
   ========================================================================== */

.centered-top-container {
  position: sticky !important;
  top: 0 !important;
  z-index: 50 !important;
  background-color: var(--md-sys-color-surface) !important;
  padding: 12px 0 !important;
  margin-bottom: 16px !important;
  width: 100% !important;
}

.centered-top {
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  width: 100% !important;
}

.blog-name {
  margin: 0 !important;
  text-align: left !important;
}

.Header h1 {
  font-family: var(--md-sys-font-brand) !important;
  font-size: 1.35rem !important;
  font-weight: 700 !important;
  letter-spacing: -0.25px !important;
  color: var(--md-sys-color-on-surface) !important;
  margin: 0 !important;
}

.Header h1 a {
  color: var(--md-sys-color-on-surface) !important;
}

.Header p {
  font-size: 0.8125rem !important;
  color: var(--md-sys-color-on-surface-variant) !important;
  margin: 2px 0 0 0 !important;
}

.top-bar-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.md3-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--md-sys-radius);
  background-color: var(--md-sys-color-surface-container);
  color: var(--md-sys-color-on-surface);
  cursor: pointer;
  transition: background-color 0.15s ease;
}

.md3-icon-btn:hover {
  background-color: var(--md-sys-color-surface-container-high);
}

/* ==========================================================================
   ORDINARY POSTS STREAM
   ========================================================================== */

body:not(.item-view) .Blog .blog-posts .post-outer-container {
  display: flex !important;
  flex-direction: column !important;
  background-color: var(--md-sys-color-surface-container-low) !important;
  border-radius: var(--md-sys-radius) !important;
  padding: 18px !important;
  margin-bottom: 16px !important;
  box-shadow: var(--md-sys-elevation-1) !important;
  transition: transform 0.2s ease, box-shadow 0.2s ease, opacity 0.2s ease !important;
}

body:not(.item-view) .Blog .blog-posts .post-outer-container:hover {
  transform: translateY(-2px) !important;
  box-shadow: var(--md-sys-elevation-2) !important;
}

.Blog .post {
  display: flex !important;
  flex-direction: column !important;
}

.Blog .post-title,
.Blog .post-title a {
  order: 1 !important;
  font-family: var(--md-sys-font-brand) !important;
  font-size: 1.3rem !important;
  font-weight: 700 !important;
  line-height: 1.35 !important;
  color: var(--md-sys-color-on-surface) !important;
  margin: 0 0 6px 0 !important;
  float: none !important;
}

.Blog .post-header {
  order: 2 !important;
  font-size: 0.8125rem !important;
  color: var(--md-sys-color-on-surface-variant) !important;
  margin-bottom: 8px !important;
}

.post-share-header-bar {
  order: 3 !important;
  margin: 0 0 14px 0 !important;
  display: flex !important;
  align-items: center !important;
}

body:not(.item-view) .Blog .post-body {
  order: 4 !important;
  display: flex !important;
  flex-direction: row !important;
  justify-content: space-between !important;
  align-items: flex-start !important;
  gap: 16px !important;
  margin: 0 0 16px 0 !important;
  color: var(--md-sys-color-on-surface-variant) !important;
  font-size: 0.9375rem !important;
  line-height: 1.6 !important;
}

body:not(.item-view) .Blog .post-body .snippet-thumbnail {
  order: 2 !important;
  border-radius: var(--md-sys-radius) !important;
  overflow: hidden !important;
  width: 96px !important;
  height: 96px !important;
  min-width: 96px !important;
  flex-shrink: 0 !important;
  background-color: var(--md-sys-color-surface-container) !important;
  margin: 0 !important;
  float: none !important;
}

body:not(.item-view) .Blog .post-body .snippet-thumbnail img {
  border-radius: var(--md-sys-radius) !important;
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  display: block !important;
}

body:not(.item-view) .Blog .post-body .post-snippet,
body:not(.item-view) .Blog .post-body p {
  order: 1 !important;
  flex: 1 1 auto !important;
  min-width: 0 !important;
  margin: 0 !important;
  overflow-wrap: break-word !important;
  word-break: normal !important;
}

body:not(.item-view) .Blog .post-bottom {
  order: 5 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: flex-start !important;
  margin-top: auto !important;
}

.md3-share-trigger {
  display: inline-flex !important;
  align-items: center !important;
  gap: 6px !important;
  background-color: var(--md-sys-color-secondary-container) !important;
  color: var(--md-sys-color-on-secondary-container) !important;
  border-radius: var(--md-sys-radius) !important;
  padding: 6px 14px !important;
  font-weight: 500 !important;
  font-size: 0.8125rem !important;
  text-decoration: none !important;
  cursor: pointer;
  width: fit-content;
}

.Blog .jump-link {
  float: none !important;
  margin: 0 !important;
}

.Blog .jump-link a {
  display: inline-flex !important;
  align-items: center !important;
  background-color: var(--md-sys-color-primary) !important;
  color: var(--md-sys-color-on-primary) !important;
  border-radius: var(--md-sys-radius) !important;
  padding: 8px 18px !important;
  font-weight: 500 !important;
  font-size: 0.8125rem !important;
  letter-spacing: 0.1px !important;
  text-decoration: none !important;
  box-shadow: var(--md-sys-elevation-1) !important;
  cursor: pointer;
}

/* ==========================================================================
   ORIGINAL BLOGGER PAGINATION (MATERIAL DESIGN 3 TONAL BUTTONS)
   ========================================================================== */

.blog-pager {
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  gap: 12px !important;
  margin: 28px 0 12px 0 !important;
  padding: 0 !important;
  width: 100% !important;
}

.blog-pager-older-link,
.blog-pager-newer-link,
.blog-pager a {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 6px !important;
  background-color: var(--md-sys-color-surface-container) !important;
  color: var(--md-sys-color-on-surface) !important;
  border-radius: var(--md-sys-radius) !important;
  padding: 10px 20px !important;
  font-family: var(--md-sys-font-brand) !important;
  font-size: 0.875rem !important;
  font-weight: 600 !important;
  text-decoration: none !important;
  box-shadow: var(--md-sys-elevation-1) !important;
  transition: background-color 0.15s ease, transform 0.15s ease !important;
}

.blog-pager-older-link:hover,
.blog-pager-newer-link:hover,
.blog-pager a:hover {
  background-color: var(--md-sys-color-surface-container-high) !important;
  color: var(--md-sys-color-primary) !important;
  transform: translateY(-1px) !important;
}

.blog-pager-older-link {
  margin-left: auto !important;
}

/* ==========================================================================
   SINGLE ARTICLE VIEW
   ========================================================================== */

body.item-view .Blog .blog-posts .post-outer-container {
  display: block !important;
  background-color: transparent !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 0 24px 0 !important;
}

body.item-view .Blog .post {
  display: block !important;
  width: 100% !important;
}

body.item-view .post-title,
body.item-view .post-title a {
  font-family: var(--md-sys-font-brand) !important;
  font-size: 2rem !important;
  line-height: 1.25 !important;
  font-weight: 700 !important;
  margin: 0 0 10px 0 !important;
  color: var(--md-sys-color-on-surface) !important;
  display: block !important;
}

body.item-view .post-header {
  font-size: 0.875rem !important;
  color: var(--md-sys-color-on-surface-variant) !important;
  margin-bottom: 12px !important;
  display: block !important;
}

body.item-view .post-body,
body.item-view .Blog .post-body {
  display: block !important;
  width: 100% !important;
  max-width: 100% !important;
  font-size: 1.0625rem !important;
  line-height: 1.8 !important;
  color: var(--md-sys-color-on-surface) !important;
  margin: 0 0 24px 0 !important;
  overflow-wrap: break-word !important;
  word-break: normal !important;
}

body.item-view .post-body p {
  display: block !important;
  width: 100% !important;
  max-width: 100% !important;
  margin-bottom: 1.25rem !important;
  overflow-wrap: break-word !important;
  word-break: normal !important;
}

body.item-view .post-body h1 { font-size: 1.75rem; font-weight: 600; margin: 2rem 0 1rem; }
body.item-view .post-body h2 { font-size: 1.5rem; font-weight: 600; margin: 1.75rem 0 0.875rem; }
body.item-view .post-body h3 { font-size: 1.25rem; font-weight: 600; margin: 1.5rem 0 0.75rem; }
body.item-view .post-body h4 { font-size: 1.1rem; font-weight: 600; margin: 1.25rem 0 0.5rem; }

body.item-view .post-body blockquote {
  margin: 1.5rem 0 !important;
  padding: 0.8rem 1.25rem !important;
  border-left: 4px solid var(--md-sys-color-primary) !important;
  background-color: var(--md-sys-color-surface-container-low) !important;
  border-radius: var(--md-sys-radius) !important;
  color: var(--md-sys-color-on-surface-variant) !important;
  font-style: normal;
}

body.item-view .post-body code {
  font-family: var(--md-sys-font-mono) !important;
  font-size: 85% !important;
  padding: 0.2em 0.4em !important;
  border-radius: 6px !important;
  background-color: var(--md-sys-color-surface-container) !important;
  color: var(--md-sys-color-on-surface) !important;
}

body.item-view .post-body pre {
  margin: 1.5rem 0 !important;
  padding: 1rem 1.25rem !important;
  background-color: var(--md-sys-color-surface-container-low) !important;
  border-radius: var(--md-sys-radius) !important;
  overflow-x: auto !important;
  font-family: var(--md-sys-font-mono) !important;
  font-size: 0.875rem !important;
  line-height: 1.5 !important;
}

body.item-view .post-body pre code {
  padding: 0 !important;
  background-color: transparent !important;
  font-size: inherit !important;
}

body.item-view .post-body table {
  width: 100% !important;
  border-collapse: collapse !important;
  border-radius: var(--md-sys-radius);
  overflow: hidden;
  margin: 1.5rem 0;
  font-size: 0.9375rem;
}

body.item-view .post-body th,
body.item-view .post-body td {
  padding: 8px 14px;
  text-align: left;
}

body.item-view .post-body th {
  font-weight: 600;
  background-color: var(--md-sys-color-surface-container-high);
}

body.item-view .post-body tr:nth-child(even) {
  background-color: var(--md-sys-color-surface-container-low);
}

body.item-view .post-body ul,
body.item-view .post-body ol {
  padding-left: 2rem;
  margin-bottom: 1.25rem;
}

body.item-view .post-body li {
  margin-bottom: 0.35rem;
}

body.item-view .post-body img {
  max-width: 100% !important;
  height: auto !important;
  border-radius: var(--md-sys-radius);
  margin: 1.5rem auto !important;
  display: block !important;
}

body.item-view .post-body .separator {
  clear: both !important;
  text-align: center !important;
  margin: 1.5rem 0 !important;
}

body.item-view .post-body .separator a {
  float: none !important;
  margin: 0 auto !important;
  display: inline-block !important;
}

/* ==========================================================================
   AUTHOR PROFILE CARD
   ========================================================================== */

.md3-profile-card {
  display: flex;
  align-items: center;
  gap: 16px;
  background-color: var(--md-sys-color-surface-container-low);
  border-radius: var(--md-sys-radius);
  padding: 18px;
  margin: 28px 0;
}

.md3-profile-avatar {
  width: 52px;
  height: 52px;
  border-radius: var(--md-sys-radius);
  object-fit: cover;
  background-color: var(--md-sys-color-surface-container-high);
}

.md3-profile-info {
  flex: 1;
}

.md3-profile-role {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  color: var(--md-sys-color-primary);
}

.md3-profile-name {
  font-size: 1.0625rem;
  font-weight: 700;
  color: var(--md-sys-color-on-surface);
  margin: 2px 0;
}

.md3-profile-bio {
  font-size: 0.8125rem;
  color: var(--md-sys-color-on-surface-variant);
  line-height: 1.5;
}

/* ==========================================================================
   COLLAPSIBLE COMMENTS
   ========================================================================== */

.comments-collapse-container {
  margin-top: 36px;
  border-radius: var(--md-sys-radius);
  background-color: var(--md-sys-color-surface-container-low);
  overflow: hidden;
}

.comments-collapse-btn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 16px 20px;
  background-color: transparent;
  color: var(--md-sys-color-on-surface);
  font-family: var(--md-sys-font-brand);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.15s ease;
}

.comments-collapse-btn:hover {
  background-color: var(--md-sys-color-surface-container);
}

.comments-collapse-left {
  display: flex;
  align-items: center;
  gap: 10px;
}

.comments-collapse-icon {
  transition: transform 0.2s ease;
}

.comments-collapse-container.expanded .comments-collapse-icon {
  transform: rotate(180deg);
}

.comments-collapse-body {
  display: none;
  padding: 0 20px 20px 20px;
}

.comments-collapse-container.expanded .comments-collapse-body {
  display: block;
}

#comments {
  background: transparent !important;
  padding: 0 !important;
  margin-top: 10px !important;
}

#comments h3.title {
  display: none !important;
}

#comments .comment {
  background-color: var(--md-sys-color-surface-container) !important;
  border-radius: var(--md-sys-radius) !important;
  padding: 14px !important;
  margin-bottom: 12px !important;
}

#comments .avatar-image-container {
  width: 36px !important;
  height: 36px !important;
  border-radius: var(--md-sys-radius) !important;
  overflow: hidden !important;
}

#comments .comment-block {
  margin-left: 46px !important;
}

#comments .comment-header .user {
  font-weight: 600 !important;
  color: var(--md-sys-color-on-surface) !important;
}

#comments .comment-header .datetime a {
  font-size: 0.75rem !important;
  color: var(--md-sys-color-on-surface-variant) !important;
}

#comments .comment-body {
  font-size: 0.875rem !important;
  margin-top: 6px !important;
}

.comment-form {
  border-radius: var(--md-sys-radius);
  overflow: hidden;
  margin-top: 16px;
  background-color: var(--md-sys-color-surface);
}

#comment-editor {
  width: 100% !important;
  min-height: 220px !important;
  border: none !important;
}

html[data-theme='dark'] #comment-editor,
:root:not([data-theme='light']) #comment-editor {
  filter: invert(0.88) hue-rotate(180deg) contrast(1.05);
  background: transparent !important;
}

/* ==========================================================================
   PURE ICONS SHARE MODAL
   ========================================================================== */

.md3-modal-backdrop {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  background-color: rgba(0, 0, 0, 0.55);
  backdrop-filter: blur(6px);
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.2s ease, visibility 0.2s ease;
}

.md3-modal-backdrop.active {
  opacity: 1 !important;
  visibility: visible !important;
}

.md3-modal-card {
  width: 100%;
  max-width: 440px;
  background-color: var(--md-sys-color-surface);
  border-radius: var(--md-sys-radius);
  padding: 22px;
  box-shadow: var(--md-sys-elevation-3);
  transform: scale(0.96);
  transition: transform 0.2s cubic-bezier(0.2, 0, 0, 1);
}

.md3-modal-backdrop.active .md3-modal-card {
  transform: scale(1);
}

.md3-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
}

.md3-modal-title {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--md-sys-color-on-surface);
}

.md3-share-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr) !important;
  gap: 8px;
  margin-bottom: 24px;
  width: 100%;
  align-items: center;
  justify-items: center;
}

.md3-share-btn-item {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  border-radius: var(--md-sys-radius);
  background: transparent !important;
  background-color: transparent !important;
  color: var(--md-sys-color-on-surface);
  text-decoration: none;
  cursor: pointer;
  transition: transform 0.18s ease, opacity 0.18s ease;
}

.md3-share-btn-item:hover {
  transform: scale(1.2);
  opacity: 0.85;
  background: transparent !important;
}

.md3-share-btn-item svg {
  width: 28px;
  height: 28px;
  flex-shrink: 0;
}

.md3-copy-container {
  display: flex;
  align-items: center;
  background-color: var(--md-sys-color-surface-container);
  border-radius: var(--md-sys-radius);
  padding: 4px 4px 4px 12px;
  margin-bottom: 12px;
}

.md3-copy-input {
  flex: 1;
  background: transparent;
  color: var(--md-sys-color-on-surface-variant);
  font-family: inherit;
  font-size: 0.8125rem;
  outline: none;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.md3-copy-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background-color: var(--md-sys-color-primary);
  color: var(--md-sys-color-on-primary);
  border-radius: var(--md-sys-radius);
  padding: 8px 16px;
  font-size: 0.8125rem;
  font-weight: 600;
  cursor: pointer;
  transition: opacity 0.15s ease;
}

.md3-copy-submit:hover {
  opacity: 0.92;
}

.md3-device-share-btn {
  display: none;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  height: 42px;
  border-radius: var(--md-sys-radius);
  background-color: var(--md-sys-color-surface-container-high);
  color: var(--md-sys-color-on-surface);
  font-family: var(--md-sys-font-brand);
  font-size: 0.8125rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.15s ease;
}

.md3-device-share-btn:hover {
  background-color: var(--md-sys-color-surface-container-highest);
}

.md3-device-share-btn .material-symbols-outlined {
  font-size: 18px;
}

/* ==========================================================================
   LIVE SEARCH MODAL
   ========================================================================= */

.md3-search-box {
  display: flex;
  align-items: center;
  gap: 10px;
  background-color: var(--md-sys-color-surface-container);
  border-radius: var(--md-sys-radius);
  padding: 4px 12px;
}

.md3-search-box input {
  width: 100%;
  height: 44px;
  background: transparent;
  color: var(--md-sys-color-on-surface);
  font-family: inherit;
  font-size: 0.9375rem;
  outline: none;
}

.md3-live-results {
  display: none;
  flex-direction: column;
  margin-top: 10px;
  max-height: 380px;
  overflow-y: auto;
  border-radius: var(--md-sys-radius);
  background-color: var(--md-sys-color-surface-container-low);
}

.md3-live-results.has-results {
  display: flex;
}

.md3-live-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border-radius: var(--md-sys-radius);
  color: var(--md-sys-color-on-surface);
  text-decoration: none;
  transition: background-color 0.15s ease;
}

.md3-live-item:hover {
  background-color: var(--md-sys-color-surface-container-high);
}

.md3-live-thumb {
  width: 44px;
  height: 44px;
  border-radius: var(--md-sys-radius);
  object-fit: cover;
  flex-shrink: 0;
  background-color: var(--md-sys-color-surface-container);
}

.md3-live-text {
  flex: 1;
  min-width: 0;
}

.md3-live-title {
  font-size: 0.875rem;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.md3-live-meta {
  font-size: 0.75rem;
  color: var(--md-sys-color-on-surface-variant);
  margin-top: 2px;
}

.md3-live-status {
  padding: 14px;
  text-align: center;
  font-size: 0.8125rem;
  color: var(--md-sys-color-on-surface-variant);
}

/* ==========================================================================
   FOOTER & GITHUB BADGE
   ========================================================================== */

.footer {
  margin-top: 36px !important;
  padding: 24px 0 !important;
  text-align: center !important;
  font-size: 0.8125rem !important;
  color: var(--md-sys-color-on-surface-variant) !important;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.md3-github-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  border-radius: var(--md-sys-radius);
  background-color: var(--md-sys-color-surface-container-low);
  color: var(--md-sys-color-on-surface);
  font-weight: 500;
  font-size: 0.8125rem;
  transition: background-color 0.15s ease, transform 0.15s ease;
}

.md3-github-badge:hover {
  background-color: var(--md-sys-color-surface-container-high);
  transform: translateY(-1px);
}

.Attribution a {
  color: var(--md-sys-color-primary) !important;
}

body.script:
//
document.addEventListener('DOMContentLoaded', function() {
  // 1. Enforce Client-Side 300-char Limit on Existing Snippets
  document.querySelectorAll('.post-snippet').forEach(function(el) {
    var raw = el.textContent.trim();
    if (raw.length > 300) {
      el.textContent = raw.substring(0, 300).trim() + '...';
    }
  });

  // 2. Collapsible Comments Section
  var commentsSection = document.getElementById('comments');
  if (commentsSection) {
    var commentCountBadge = document.querySelector('.num_comments');
    var countText = 'Comments';
    if (commentCountBadge) {
      countText = commentCountBadge.textContent.trim();
    }

    var collapseContainer = document.createElement('div');
    collapseContainer.className = 'comments-collapse-container';

    var toggleBtn = document.createElement('button');
    toggleBtn.type = 'button';
    toggleBtn.className = 'comments-collapse-btn';
    toggleBtn.innerHTML = `
      <div class="comments-collapse-left">
        <span class="material-symbols-outlined">chat_bubble</span>
        <span class="comments-collapse-label">View ${countText}</span>
      </div>
      <span class="material-symbols-outlined comments-collapse-icon">expand_more</span>
    `;

    var collapseBody = document.createElement('div');
    collapseBody.className = 'comments-collapse-body';

    commentsSection.parentNode.insertBefore(collapseContainer, commentsSection);
    collapseContainer.appendChild(toggleBtn);
    collapseContainer.appendChild(collapseBody);
    collapseBody.appendChild(commentsSection);

    toggleBtn.addEventListener('click', function() {
      var isExpanded = collapseContainer.classList.toggle('expanded');
      var label = toggleBtn.querySelector('.comments-collapse-label');
      label.textContent = isExpanded ? 'Hide Comments' : `View ${countText}`;
    });
  }

  // 3. Pure Icons MD3 Share Modal
  var shareModal = document.getElementById('shareModal');
  var shareCloseBtn = document.getElementById('shareCloseBtn');
  var shareUrlField = document.getElementById('shareUrlField');
  var copyUrlBtn = document.getElementById('copyUrlBtn');
  var deviceShareBtn = document.getElementById('deviceShareBtn');

  document.querySelectorAll('.md3-share-trigger').forEach(function(btn) {
    btn.addEventListener('click', function(e) {
      e.preventDefault();
      e.stopPropagation();
      var title = btn.getAttribute('data-title') || document.title;
      var url = btn.getAttribute('data-url') || window.location.href;

      if (shareModal) {
        shareUrlField.value = url;
        document.getElementById('shareWA').href = 'https://api.whatsapp.com/send?text=' + encodeURIComponent(title + ' ' + url);
        document.getElementById('shareX').href = 'https://twitter.com/intent/tweet?text=' + encodeURIComponent(title) + '&url=' + encodeURIComponent(url);
        document.getElementById('shareFB').href = 'https://www.facebook.com/sharer/sharer.php?u=' + encodeURIComponent(url);
        document.getElementById('shareTG').href = 'https://t.me/share/url?url=' + encodeURIComponent(url) + '&text=' + encodeURIComponent(title);
        document.getElementById('shareMail').href = 'mailto:?subject=' + encodeURIComponent(title) + '&body=' + encodeURIComponent(url);

        if (deviceShareBtn) {
          if (navigator.share) {
            deviceShareBtn.style.display = 'inline-flex';
            deviceShareBtn.onclick = function() {
              navigator.share({ title: title, url: url }).catch(function() {});
            };
          } else {
            deviceShareBtn.style.display = 'none';
          }
        }

        shareModal.classList.add('active');
      }
    });
  });

  if (shareCloseBtn && shareModal) {
    shareCloseBtn.addEventListener('click', function() {
      shareModal.classList.remove('active');
    });
  }

  if (copyUrlBtn && shareUrlField) {
    copyUrlBtn.addEventListener('click', function() {
      navigator.clipboard.writeText(shareUrlField.value).then(function() {
        copyUrlBtn.textContent = 'Copied!';
        setTimeout(function() { copyUrlBtn.textContent = 'Copy'; }, 2000);
      });
    });
  }

  // 4. Theme Management (Default: Dark)
  var themeBtn = document.getElementById('themeToggleBtn');
  var themeIcon = document.getElementById('themeIcon');

  function updateThemeDisplay(theme) {
    document.documentElement.setAttribute('data-theme', theme);
    if (themeIcon) {
      themeIcon.textContent = theme === 'dark' ? 'light_mode' : 'dark_mode';
    }
  }

  var currentTheme = document.documentElement.getAttribute('data-theme') || 'dark';
  updateThemeDisplay(currentTheme);

  if (themeBtn) {
    themeBtn.addEventListener('click', function() {
      var nextTheme = document.documentElement.getAttribute('data-theme') === 'light' ? 'dark' : 'light';
      localStorage.setItem('md3_theme', nextTheme);
      updateThemeDisplay(nextTheme);
    });
  }

  // 5. YouTube-Style Live Search Preview
  var searchModal = document.getElementById('searchModal');
  var searchOpenBtn = document.getElementById('searchOpenBtn');
  var searchCloseBtn = document.getElementById('searchCloseBtn');
  var searchInput = document.getElementById('searchQueryInput');
  var liveResults = document.getElementById('searchLiveResults');
  var searchDebounce;

  if (searchOpenBtn && searchModal) {
    searchOpenBtn.addEventListener('click', function() {
      searchModal.classList.add('active');
      setTimeout(function() { searchInput.focus(); }, 100);
    });
  }

  if (searchCloseBtn && searchModal) {
    searchCloseBtn.addEventListener('click', function() {
      searchModal.classList.remove('active');
    });
  }

  function escapeSearchHTML(str) {
    return str.replace(/[&<>'"]/g, function(tag) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[tag] || tag;
    });
  }

  function renderLiveResults(posts, query) {
    if (!posts || posts.length === 0) {
      liveResults.innerHTML = '<div class="md3-live-status">No matching articles found</div>';
      liveResults.classList.add('has-results');
      return;
    }

    var html = '';
    posts.slice(0, 5).forEach(function(post) {
      var title = post.title.$t;
      var link = '#';
      post.link.forEach(function(l) {
        if (l.rel === 'alternate') link = l.href;
      });
      var thumb = post.media$thumbnail ? post.media$thumbnail.url : '';
      var published = new Date(post.published.$t).toLocaleDateString(undefined, {
        year: 'numeric', month: 'short', day: 'numeric'
      });

      html += `
        <a href="${link}" class="md3-live-item">
          ${thumb ? `<img class="md3-live-thumb" src="${thumb}" alt="" />` : '<span class="material-symbols-outlined" style="color:var(--md-sys-color-primary);">article</span>'}
          <div class="md3-live-text">
            <div class="md3-live-title">${escapeSearchHTML(title)}</div>
            <div class="md3-live-meta">${published}</div>
          </div>
          <span class="material-symbols-outlined" style="font-size:18px;color:var(--md-sys-color-on-surface-variant);">north_west</span>
        </a>
      `;
    });

    liveResults.innerHTML = html;
    liveResults.classList.add('has-results');
  }

  if (searchInput) {
    searchInput.addEventListener('input', function() {
      var query = this.value.trim();
      clearTimeout(searchDebounce);

      if (query.length < 2) {
        liveResults.innerHTML = '';
        liveResults.classList.remove('has-results');
        return;
      }

      searchDebounce = setTimeout(function() {
        liveResults.innerHTML = '<div class="md3-live-status">Searching...</div>';
        liveResults.classList.add('has-results');

        fetch('/feeds/posts/summary?alt=json&max-results=6&q=' + encodeURIComponent(query))
          .then(function(res) { return res.json(); })
          .then(function(data) {
            var entries = data.feed ? data.feed.entry : [];
            renderLiveResults(entries, query);
          })
          .catch(function() {
            liveResults.innerHTML = '<div class="md3-live-status">Press Enter to search</div>';
          });
      }, 250);
    });
  }

  // Close Modals on Escape or Backdrop Click
  window.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') {
      if (searchModal) searchModal.classList.remove('active');
      if (shareModal) shareModal.classList.remove('active');
    }
  });

  [searchModal, shareModal].forEach(function(modal) {
    if (modal) {
      modal.addEventListener('click', function(e) {
        if (e.target === modal) modal.classList.remove('active');
      });
    }
  });
});
//
